from typing import Iterator, Dict, Any
import logging

def read_jsonl(file_path: str) -> Iterator[Dict[Any, Any]]:
    """Yield valid JSON objects from a JSONL file, logging invalid lines."""
    with open(file_path, 'r', encoding='utf-8') as f:
        for line_num, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError as e:
                logging.warning(f"Line {line_num} decode error: {e}")
